  _ensureInit() {
    if (!this.data) {
      this.data = {};
    }
    if (!this.data.locations || typeof this.data.locations !== 'object') {
      this.data.locations = {};
    }
    this._checkInvariants();
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === 'object', "Model data must be an object");
    this.invariant(this.data.locations && typeof this.data.locations === 'object', "Locations store must be an object");
    for (const [key, loc] of Object.entries(this.data.locations)) {
      this.invariant(typeof key === 'string' && key.trim().length > 0, "Location key must be a non-empty string");
      this.invariant(loc && typeof loc === 'object', "Stored location must be an object");
      this.invariant(typeof loc.name === 'string' && loc.name.trim().length > 0, "Location name must be a non-empty string");
      this.invariant(typeof loc.lat === 'number' && !isNaN(loc.lat) && loc.lat >= -90 && loc.lat <= 90, "Latitude must be within [-90, 90]");
      this.invariant(typeof loc.lon === 'number' && !isNaN(loc.lon) && loc.lon >= -180 && loc.lon <= 180, "Longitude must be within [-180, 180]");
    }
  },

  _toRad(deg) {
    return (deg * Math.PI) / 180;
  },

  _haversineKm(lat1, lon1, lat2, lon2) {
    const R = 6371.0088; // Earth's mean radius in kilometers
    const dLat = this._toRad(lat2 - lat1);
    const dLon = this._toRad(lon2 - lon1);
    const radLat1 = this._toRad(lat1);
    const radLat2 = this._toRad(lat2);

    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
              Math.cos(radLat1) * Math.cos(radLat2) *
              Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  },

  _convertDistance(km, unit) {
    const u = (unit || 'km').toLowerCase().trim();
    switch (u) {
      case 'km':
      case 'kilometer':
      case 'kilometers':
        return km;
      case 'm':
      case 'meter':
      case 'meters':
        return km * 1000;
      case 'mi':
      case 'mile':
      case 'miles':
        return km * 0.621371192237334;
      case 'nm':
      case 'nauticalmile':
      case 'nauticalmiles':
        return km * 0.5399568034557235;
      default:
        this.ensure(false, `Unsupported unit: '${unit}'. Supported units: km, m, mi, nm.`);
    }
  },

  _resolveLocation(loc, label) {
    this.ensure(loc !== undefined && loc !== null, `${label} must be provided`);
    if (typeof loc === 'string') {
      const key = loc.trim();
      const existing = this.data.locations[key];
      this.ensure(existing !== undefined, `Location '${key}' not found in registered locations`);
      return existing;
    }
    if (typeof loc === 'object') {
      this.ensure(typeof loc.lat === 'number' && !isNaN(loc.lat) && loc.lat >= -90 && loc.lat <= 90, `${label}.lat must be a number between -90 and 90`);
      this.ensure(typeof loc.lon === 'number' && !isNaN(loc.lon) && loc.lon >= -180 && loc.lon <= 180, `${label}.lon must be a number between -180 and 180`);
      return {
        name: typeof loc.name === 'string' ? loc.name : 'custom',
        lat: loc.lat,
        lon: loc.lon
      };
    }
    this.ensure(false, `${label} must be a location name string or an object with { lat, lon }`);
  },

