    this._checkInvariants();
    this.changed("locationAdded", locationEntry);

    // Postconditions
    this.ensure(this.data.locations[key] !== undefined, "Location must be stored in data model");
    return locationEntry;
  },

  getDistance(msg) {
    this._ensureInit();
    const payload = msg && msg.payload ? msg.payload : {};
    const { locA, locB, unit } = payload;

    // Preconditions
    this.ensure(locA !== undefined && locA !== null, "locA is required");
    this.ensure(locB !== undefined && locB !== null, "locB is required");

    const resolvedA = this._resolveLocation(locA, "locA");
    const resolvedB = this._resolveLocation(locB, "locB");

    const distanceKm = this._haversineKm(resolvedA.lat, resolvedA.lon, resolvedB.lat, resolvedB.lon);
    const converted = this._convertDistance(distanceKm, unit || 'km');
    const resultUnit = (unit || 'km').toLowerCase().trim();

    const result = {
      from: resolvedA.name,
      to: resolvedB.name,
      distance: converted,
      unit: resultUnit
    };

    // Postconditions
    this.ensure(typeof result.distance === 'number' && !isNaN(result.distance) && result.distance >= 0, "Computed distance must be a non-negative number");
