    this._ensureInit();
    const payload = msg && msg.payload ? msg.payload : {};
    const { lat, lon, radiusKm } = payload;

    // Preconditions
    this.ensure(typeof lat === 'number' && !isNaN(lat) && lat >= -90 && lat <= 90, "Latitude must be a number between -90 and 90");
    this.ensure(typeof lon === 'number' && !isNaN(lon) && lon >= -180 && lon <= 180, "Longitude must be a number between -180 and 180");
    this.ensure(typeof radiusKm === 'number' && !isNaN(radiusKm) && radiusKm >= 0, "radiusKm must be a non-negative number");

